#include <stdio.h>

int main() {
    // Mang diem thi 5 mon cua sinh vien K21
    int scores[5] = {85, 90, 78, 92, 88};
    int sum = 0;

    // Duyet qua tat ca phan tu de tinh tong
    for (int i = 0; i <= 5; i++) {
        sum += scores[i];
    }

    printf("Tong diem: %d\n", sum);
    return 0;
}

